export type RenderTargetType = 
    | 'offscreen'   // Cleared every frame (loadOp: 'clear') - minimaps, monitors
    | 'persistent'  // Retains pixels across frames (loadOp: 'load') - drawing boards, heatmaps
    | 'feedback'    // Previous-frame ping-pong feedback
    | 'storage'     // Compute shader writable storage texture
    | 'pingpong'    // Double-buffered compute/render target
    | 'gbuffer';    // Multi-render-target deferred buffer (Albedo, Normal, Position)

export type RenderTargetCameraOption = 
    | 'ortho'        // Dedicated 1:1 pixel orthographic camera (default)
    | 'perspective'  // Dedicated 3D perspective camera (FOV 45°, depth enabled)
    | 'scene'        // Automatically mirrors the main scene camera
    | 'none' | false // Identity orthographic projection (no camera movement)
    | Camera;        // Explicit custom Camera instance

export interface RenderTargetOptions {
    /** Optional friendly name or label for GPU debugging */
    name?: string;
    label?: string;

    /** Texture width in pixels (default: 512) */
    width?: number;

    /** Texture height in pixels (default: 512) */
    height?: number;

    /** Target output type (default: 'offscreen') */
    type?: RenderTargetType;

    /** Texture format (default: preferred canvas format) */
    format?: GPUTextureFormat;

    /** Initial entities to render exclusively into this render target */
    entities?: Entity[];

    /** Explicit layer bit index (0..31). If omitted, auto-allocated (layer 2..29) */
    layer?: number;

    /** Camera configuration for this render target */
    camera?: RenderTargetCameraOption;

    /** Background clear color (e.g. Color.TRANSPARENT, new Color(0,0,0,0), or [r, g, b, a]) */
    clearColor?: Color | { r: number; g: number; b: number; a: number } | [number, number, number, number];

    /** Automatically register added entities in the scene (default: true) */
    autoAddToScene?: boolean;
}

