import { Scene, Model, Math3D, Color, Circle, OrbitCameraController, RenderTarget } from "retiam";

export class PersistentDrawShowcase extends Scene {
    public async run() {
        this.camera.position.set([0, 0, 15]);
        new OrbitCameraController(this, this.camera);

        // 1. Clean Physics3D-style RenderTarget initialization
        const canvas = new RenderTarget(this, {
            width: 1024,
            height: 1024,
            type: "persistent",
            clearColor: new Color(0.02, 0.05, 0.1, 1.0)
        });

        // 2. Add brush directly
        const brush = new Circle(25);
        brush.paint.fill = new Color(0.2, 0.9, 0.6, 1.0);
        canvas.add(brush);

        this.always(() => {
            const t = this.time * 0.003;
            brush.transform.position.set([Math.sin(t) * 350, Math.sin(t * 2) * 350, 0]);
            brush.paint.fill.r = Math.sin(t * 0.5) * 0.5 + 0.5;
            brush.paint.fill.b = Math.cos(t * 0.5) * 0.5 + 0.5;
        });

        // 3. Mount onto a 3D TV using toSprite()
        const tvCasing = new Model(Math3D.createCube(6));
        tvCasing.transform.setScale(1.0, 1.0, 0.05);

        const tvScreen = canvas.toSprite(6, 6);
        tvScreen.transform.position.z = 3.05;
        tvScreen.transform.setScale(0.9, 0.9, 1.0);

        tvCasing.add(tvScreen);
        this.add(tvCasing);
    }
}

